      SUBROUTINE EL242CC     STEP THROUGH BEND ELEMENT WITH POSSIBLE FRINGE FIELDSC     (ROTAT ELEMENT)C      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM0C.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM2D.CIN'      INCLUDE 'ELM4E.CIN'      INCLUDE 'ELM8A.CIN'      INCLUDE 'ELM8G.CIN'      INCLUDE 'ELM8H.CIN'      INCLUDE 'ELM10B.CIN'      INCLUDE 'ELM10E.CIN'      INCLUDE 'ELM13A.CIN'      INCLUDE 'ELM13B.CIN'      INCLUDE 'ELM13C.CIN'      INCLUDE 'ELM16B.CIN'      INCLUDE 'FLUSHC.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'LXRAN.CIN'      INCLUDE 'OCP.CIN'      INCLUDE 'R2P.CIN'      INCLUDE 'R3P.CIN'      INCLUDE 'STEPT1.CIN'CC     LOCAL VARIABLESC      INTEGER         IDATA, IMIS       INTEGER         NUME, NUMS, NUM2I, NUM2O      INTEGER         TYPEN      LOGICAL         CKK      EXTERNAL        IDATACC     DETERMINE WHICH PARTS OF 2-4-2 ARE PRESENTC      NUMS = NUM      FFIN = .FALSE.      IF (TYPE .EQ. 2) THEN        CALL CHEK(CKK)        IF (.NOT. CKK) GO TO 200        NUM2I = NUM        NUM = NUM4        I = ISTOR(NUM)        TYPE = IDATA(I)        CALL SKETCH(NUM)        CALL DEPICT      ELSE        NUM4 = NUM      ENDIF      TILT = IPTOJ(NTILT) .NE. 0      CALL HUNT2      IF (FFOUT) THEN        NUM2O = NUM2        NUME = NUM2O      ELSE        NUME = NUM4      ENDIFC      NUM = NUMS      I = ISTOR(NUM)      TYPE = IDATA(I)      TYPEC = TYPE      IF (TYPE .EQ. 2 .AND. NUM2I + NDIF .NE. NUM4) GO TO 60      IF (FFOUT .AND. NUM4 + NDIF .NE. NUM2O) GO TO 60      GO TO 70CC     ALGEBRAIC COMBINATIONSC   60 IF (TYPE .EQ. 23 .OR. TYPE .EQ. 30) THEN        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          CALL POSTER        ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200      ENDIF      IF (NUM .LT. NUME) THEN        NUM = NUM + NDIF        I = ISTOR(NUM)        TYPE = IDATA(I)        TYPEC = TYPE        GO TO 60      ENDIFC   70 NUM = NUMS      I = ISTOR(NUM)      TYPE = IDATA(I)      BEFORE = .TRUE.CC     CHECK FOR MISALIGNMENTSC      DMC = .FALSE.      IF (ALO(1)) THEN        NMIS = NM4        NMISE = NUM4        IMIS = ISTOR(NMIS)        TYT = INT(DATA(IMIS+7))        LFM = TYT/100        RORC = MOD(TYT,10)        IR = 1        IF (FFIN .OR. FFOUT) IR = 3        DMC = LFM .GE. 1      ENDIFCC     ENTRANCE MISALIGNMENTC      IF (DMC) THEN        TYPEC = 8        LXRAN = LFM .EQ. 2        CALL SKETCH(NMISE)        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) THEN            CALL POSTER            CALL MPRINT          ENDIF        ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200      ENDIF      IF (LFM .EQ. 0 .AND. ALO(1) .AND. (FFIN .OR. FFOUT) .AND. R2P)     1    CALL UPDAT2      IF (LFM .EQ. 1 .AND. ALO(1) .AND. (FFIN .OR. FFOUT) .AND. OCP(3))     1    CALL RESET(3)CC     ROTATION OF ELEMENTC      IF (TILT) THEN        TYPEC = 20        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) CALL POSTER        ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200      ENDIFCC     ENTRANCE FRINGE FIELDC      IF (LAY) CALL CSAVE      IF (FFIN) THEN        NUM = NUM2I        I = ISTOR(NUM)        TYPE = IDATA(I)        TYPEC = TYPE        LXRAN = .TRUE.         CALL SKETCH(NUM4)        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) THEN            CALL POSTER            CALL VPRINT          ENDIF        ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200CC     ALGEBRAIC OPERATIONSC  140   IF (NDIF .GT. 0 .AND. NUM .GE. NUM4 - NDIF) GO TO 150        IF (NDIF .LT. 0 .AND. NUM .LE. NUM4 - NDIF) GO TO 150        NUM = NUM + NDIF        I = ISTOR(NUM)        TYPE = IDATA(I)        TYPEC = TYPE        IF (NV3 .GE. 1) NCT = NCT + 1        IF (TYPE .NE. 23 .AND. TYPE .NE. 30) THEN          IF (NV3 .GE. 1) THEN            CALL DERIVE          ELSE            CALL ELICIT            IF (.NOT. LSTEPN) CALL POSTER          ENDIF          IF (FLUSHL) GO TO 200          IF (TYPE .LE. 0) GO TO 200        ENDIF        GO TO 140      ENDIFCC     CENTRAL BODY OF BENDC  150 NUM = NUM4      I = ISTOR(NUM)      TYPE = IDATA(I)      TYPEC = TYPE      IF (NV3 .GE. 1 .AND. FFIN) NCT = NCT + 1      IF (FFIN .OR. DMC) CALL SKETCH(NUM)      LXRAN = .NOT. FFIN      IF (NV3 .GE. 1) THEN        CALL DERIVE      ELSE        CALL ELICIT        IF (.NOT. LSTEPN) THEN          CALL POSTER          CALL VPRINT        ENDIF      ENDIF      IF (FLUSHL) GO TO 200      IF (TYPE .LE. 0) GO TO 200CC     EXIT FRINGING FIELDC      BEFORE = .FALSE.      IF (FFOUT) THEN  170   NUM = NUM + NDIF        I = ISTOR(NUM)        TYPE = IDATA(I)        TYPEC = TYPE        IF (NV3 .GE. 1) NCT = NCT + 1        IF (TYPE .NE. 23 .AND. TYPE .NE. 30) THEN          CALL SKETCH(NUM)          LXRAN = TYPE .EQ. 2          IF (NV3 .GE. 1) THEN            CALL DERIVE          ELSE            CALL ELICIT            IF (.NOT. LSTEPN) THEN              CALL POSTER              IF (TYPE .EQ. 2) THEN                CALL VPRINT                IF (LAY .AND. PBP) CALL BPRINT              ENDIF            ENDIF          ENDIF          IF (FLUSHL) GO TO 200          IF (TYPE .LE. 0) GO TO 200        ENDIF        IF (NDIF .GT. 0 .AND. NUM .LT. NUM2O) GO TO 170        IF (NDIF .LT. 0 .AND. NUM .GT. NUM2O) GO TO 170      ENDIF      IF (NV3 .LE. 0 .AND. .NOT. LSTEPN) THEN        TYPEN = IDATA(ISTOR(NUM+NDIF))        IF (TILT .OR. (REFER .AND. TYPEN .EQ. 20)) SONLY = .TRUE.        CALL MPRINT        IF (TILT .OR. (REFER .AND. TYPEN .EQ. 20)) SONLY = .FALSE.      ENDIFCC     REVERSE ROTATION OF ELEMENTC      IF (TILT) THEN        TYPEC = 20        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) THEN            CALL POSTER            CALL MPRINT          ENDIF        ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200      ENDIFCC     SEE IF ELEMENT IS MISALIGNEDC      DMC = .FALSE.      IF (ALO(1)) THEN        NMIS = NM4        DMC = .TRUE.      ENDIFCC     EXIT MISALIGNMENTC      IF (DMC) THEN        IF (NV3 .GE. 1) THEN          IF (LFM .EQ. 0 .AND. (R2P .OR. R3P)) CALL UPDAT2        ELSE          IF (LFM .EQ. 0 .AND. R2P) CALL UPDAT2        ENDIF        TYPEC = 8        CALL SKETCH(NMIS)        IF (NV3 .GE. 1) THEN          CALL DERIVE        ELSE          CALL ELICIT          IF (.NOT. LSTEPN) THEN            CALL POSTER            CALL MPRINT          ENDIF        ENDIF        IF (FLUSHL) GO TO 200        IF (TYPE .LE. 0) GO TO 200      ENDIFC  200 RETURN      END